  [("conservar", "mantener sin cambio"), ("figuras unidas", "figuras pegadas por un lado"), ("medida", "perímetro, área o ángulo de una figura"), ("copia", "otra figura igual a la original")],
  [("Copiar los datos a la imagen", "Una figura tiene área 30 m² y perímetro 26 m. Se refleja. ¿Qué área y perímetro tiene la imagen?", ["La reflexión conserva las medidas.", "La imagen tiene lo mismo."], "Área 30 m² y perímetro 26 m"),
   ("Figuras pegadas", "Dos cuadrados de lado 2 m se pegan por un lado. ¿Cuál es el área total y el perímetro del conjunto?", ["Área: 4 + 4 = 8 m².", "Resulta un rectángulo de 4 por 2: perímetro 2 × (4 + 2) = 12 m."], "Área 8 m² y perímetro 12 m")],
  [("Sumar los perímetros de dos figuras pegadas.", "Se cuentan los lados que quedaron por dentro.", "Resta los lados pegados o calcula el perímetro del conjunto."),
   ("Recalcular desde cero el área de una imagen.", "No se usa que la imagen conserva el área.", "Copia el área del original: es la misma.")],
